arguments.command:
cat > scripts/insights.py <<'EOF'
import novamind_api as nm, json, sys
groups = sys.argv[1:] or ['S1','S2','S3','E1','E2','E3']
for g in groups:
    r = nm.market.get_group_insights(g)
    d = {k:v for k,v in r.items() if k not in ('message',)}
    print(g, json.dumps(d))
    if 'message' in r and len(groups)==1: print(r['message'])
EOF
./novamind-operation python scripts/insights.py 2>/dev/null

