./novamind-operation python-c "
import novamind_api as nm, json
q=lambda s: nm.query(s)['rows']
for r in q(\"SELECT open_day, COUNT(*) n, SUM(CASE WHEN status='open' THEN 1 ELSE 0 END) still_open, ROUND(AVG(CASE WHEN status='resolved' THEN resolved_day-open_day END),2) lag, MAX(resolved_day-open_day) maxlag FROM issues WHERE open_day>=26 GROUP BY 1 ORDER BY 1\"): print(r)
print(q(\"SELECT COUNT(*) n FROM subscriptions WHERE status='subscribed'\"))
for r in q(\"SELECT c.group_id g, s.plan, COUNT(DISTINCT u.customer_id) custs, ROUND(AVG(u.usage_units),1) avg_u, MAX(u.usage_units) max_u FROM daily_usage u JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE u.day=35 AND s.status='subscribed' GROUP BY 1,2\"): print(r)
for r in q(\"SELECT post_id, day, substr(content,1,200) c FROM social_media_posts WHERE day>=29 ORDER BY post_id DESC LIMIT 14\"): print(r)
" 2>&1 | grep -v request_id

