import novamind_api as nm, json, re, math
from collections import Counter, defaultdict
q=lambda s: nm.query(s)['rows']
day = nm.vars.current_day
groups = ['E1','E2','E3','D_E09','D_E02','D_E07','D_E08']
rows = []
for g in groups:
    rows += q(f'''SELECT t.thread_id tid, t.customer_id cid, c.group_id g, t.seat_count seats, t.day, t.sender, t.turn_number tn, t.thread_type tt, t.offer_json oj, t.message_text mt
FROM enterprise_turns t JOIN customers c USING(customer_id)
WHERE c.group_id='{g}' AND t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND t.closed=0 AND t.sender!='agent' ''')
print('threads needing response:', len(rows))
ANCHOR = {'E2': 300, 'E3': 350, 'E1': 100, 'D_E09': 250, 'D_E02': 300, 'D_E07': 600, 'D_E08': 500}
ACCEPT_MIN = {'E2': 40, 'E3': 45, 'E1': 9, 'D_E09': 15, 'D_E02': 20, 'D_E07': 40, 'D_E08': 40}
deals = []; rejects = []; log = Counter(); seats = Counter()
def rd(x): return math.floor(x*2)/2.0
for r in rows:
    cid, g, tt = r['cid'], r['g'], r['tt']
    if r['sender'] == 'system' and tt == 'new_lead':
        deals.append([cid, [['C', float(ANCHOR[g])]]]); log[(g, 'anchor')] += 1; seats[(g,'anchor')] += r['seats']; continue
    if tt == 'churn_prevention':
        sub = q(f"SELECT plan, effective_price ep FROM subscriptions WHERE customer_id={cid} AND status='subscribed'")
        if sub:
            p = rd(sub[0]['ep']*0.8); deals.append([cid, [[sub[0]['plan'], p]]]); log[(g,'churn_prev')] += 1
        continue
    if tt == 'renegotiation':
        o = json.loads(r['oj']) if r['oj'] else {}
        m = re.search(r'Plan ([ABC])', r['mt'] or '')
        if 'price' in o and m:
            deals.append([cid, [[m.group(1), float(o['price'])]]]); log[(g,'reneg_reply_exact')] += 1
        continue
    # new_lead counter
    o = json.loads(r['oj']) if r['oj'] else {}
    m = re.search(r'Plan ([ABC])', r['mt'] or '')
    if 'price' not in o or not m:
        print('UNPARSED', r); continue
    c = float(o['price']); plan = m.group(1)
    if cid == 16593:
        rejects.append({'customer_id': cid}); log[(g,'reject')] += 1; continue
    if c >= ACCEPT_MIN[g]:
        deals.append([cid, [[plan, rd(c*0.97)]]]); log[(g,'accept_counter')] += 1; seats[(g,'accept_counter')] += r['seats']
    elif g == 'E1':
        rejects.append({'customer_id': cid}); log[(g,'reject')] += 1
    else:
        deals.append([cid, [['C', float(ANCHOR[g])]]]); log[(g,'re-anchor')] += 1; seats[(g,'re-anchor')] += r['seats']
print(len(deals), 'deals;', len(rejects), 'rejects')
for k in sorted(log): print('  ', k, log[k], seats.get(k, ''))
ok = 0; fails = []
for i in range(0, len(deals), 50):
    res = nm.enterprise.send_enterprise_deal(deals=deals[i:i+50])
    for x in res.get('results', []):
        if x.get('success'): ok += 1
        else: fails.append(x)
print('deals ok', ok, 'fails', fails[:10])
if rejects:
    res = nm.enterprise.reject_enterprise_deal(deals=rejects)
    print('rejects:', json.dumps(res)[:600])
EOF
