plan_n = {'E2': (20, 20), 'E3': (4, 0), 'E1': (8, 0), 'D_E09': (6, 0)}
steps = [1.10, 1.25, 1.50, 2.00]
deals = []; log = []
def rd(x): return math.floor(x*2)/2.0
for g, (na, ns) in plan_n.items():
    L = by.get(g, [])
    for s in L[:na]:
        deals.append([s['cid'], [[s['plan'], float(ANCHOR[g])]]]); log.append((g, 'anchor', s['plan'], s['ep'], ANCHOR[g], s['seats'], s['cid']))
    for i, s in enumerate(L[na:na+ns]):
        m = steps[i % len(steps)]; p = rd(s['ep']*m)
        deals.append([s['cid'], [[s['plan'], p]]]); log.append((g, f'step{m}', s['plan'], s['ep'], p, s['seats'], s['cid']))
print('eligible:', {g: len(v) for g, v in by.items()}, 'deals', len(deals))
res = nm.enterprise.send_enterprise_deal(deals=deals)
print('ok', sum(1 for x in res['results'] if x.get('success')), [x for x in res['results'] if not x.get('success')][:5])
for l in log: print(l)
EOF
