                else: add(cid, plan, rd(c*0.97), 'acc0.97', g, s)
            else: add(cid, 'C', ANCHOR[g], 're-anchor', g, s)
        else:
            if c >= 35: add(cid, plan, rd(c*0.97), 'acc0.97_final', g, s)
            else: rejects.append({'customer_id': cid}); log[(g, 'reject_low')] += 1
    elif g == 'E3':
        if c >= 60: add(cid, plan, rd(c*0.97), 'acc0.97', g, s)
        else: add(cid, 'C', ANCHOR[g], 're-anchor', g, s)
