        if n == 1:
            if c >= 20:
                mult = [0.97, 1.10, 1.25, 1.50][cid % 4]
                add(cid, plan, rd(c*mult), f'acc{mult}', g, s)
            else: add(cid, 'C', ANCHOR[g], 're-anchor', g, s)
        else:
            if c >= 12: add(cid, plan, rd(c*0.97), 'acc0.97_final', g, s)
            else: rejects.append({'customer_id': cid}); log[(g, 'reject_low')] += 1
    elif g == 'D_E09':
        if c >= 35: add(cid, plan, rd(c*0.97), 'acc0.97', g, s)
