cand = [x for x in q("SELECT s.customer_id cid, s.effective_price ep, s.seat_count seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.group_id='E2' AND s.plan='B' AND s.status='subscribed' ORDER BY s.customer_id") if x['cid'] not in open_c]
