import novamind_api as nm, json, statistics
from collections import defaultdict, Counter
day = nm.vars.current_day
q=lambda s: nm.query(s)['rows']
rows = []
mx = q("SELECT MAX(message_id) m FROM enterprise_turns")[0]['m'] or 0
step = 500
for lo in range(0, mx+1, step):
    rows += q(f"SELECT t.message_id mid, t.thread_id tid, t.customer_id cid, c.group_id g, t.thread_type tt, t.turn_number tn, t.sender, t.day, t.seat_count seats, t.closed, t.close_reason cr, t.offer_json oj FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.message_id>{lo} AND t.message_id<={lo+step}")
threads = defaultdict(list)
for r in rows: threads[r['tid']].append(r)
subs = {r['cid']: r for r in q("SELECT s.customer_id cid, s.plan, s.effective_price ep, s.status, s.seat_count seats, s.start_day sd FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status IN ('subscribed','cancelled')")}
def offs(m):
    try:
        o = json.loads(m['oj']) if m['oj'] else []
    except Exception: o = []
    if isinstance(o, dict): return o
    return o
print("=== RENEGOTIATION threads ===")
for tid, ms in sorted(threads.items()):
    ms.sort(key=lambda r: r['tn'])
    if ms[0]['tt'] != 'renegotiation': continue
    cid = ms[0]['cid']; g = ms[0]['g']
    seq = []
    for m in ms:
        o = offs(m)
        if m['sender']=='agent': seq.append(f"A d{m['day']}:{[(x['plan'], x['price_per_seat']) for x in o] if isinstance(o, list) else o}")
        elif m['sender']=='customer': seq.append(f"C d{m['day']}:{o.get('price') if isinstance(o, dict) else o}{' ACC' if m['closed'] and m['cr']=='accepted' else ''}")
        else: seq.append(f"S d{m['day']}:{m['cr'] or ''}")
    s = subs.get(cid, {})
    print(f"  [{g}] cust {cid} seats={ms[-1]['seats']} sub_now=({s.get('plan')},{s.get('ep')},{s.get('status')}) :: " + " | ".join(seq))
print("=== ANCHOR / offer outcomes for offers sent on recent days ===")
arm = defaultdict(lambda: defaultdict(list))
for tid, ms in threads.items():
    ms.sort(key=lambda r: r['tn'])
    g = ms[0]['g']; tt = ms[0]['tt']
    if tt != 'new_lead': continue
    ag = [m for m in ms if m['sender']=='agent']
    for a in ag:
        o = offs(a)
        if not isinstance(o, list) or not o: continue
        if a['day'] < day-14: continue
        key = (g, a['day'], o[0]['plan'], o[0]['price_per_seat'] if o[0]['price_per_seat'] in (300,350,100,250,600,500,180,150) else 'other')
        nxt = [m for m in ms if m['tn']>a['tn'] and m['sender']=='customer']
        seats = ms[-1]['seats']
        if nxt:
            m = nxt[0]; oc = offs(m)
            if m['closed'] and m['cr']=='accepted': arm[key]['accept'].append((o[0]['price_per_seat'], seats))
            else: arm[key]['counter'].append((oc.get('price') if isinstance(oc, dict) else None, seats, o[0]['price_per_seat']))
        else:
            if a['closed']: arm[key]['ghost'].append(seats)
            elif any(m['closed'] for m in ms): arm[key]['closed_other'].append(seats)
            else: arm[key]['pending'].append(seats)
def qs(v):
    v = sorted(v)
    if not v: return ''
    n = len(v); return f"min {v[0]} q25 {v[n//4]} med {v[n//2]} q75 {v[(3*n)//4]} max {v[-1]}"
for k in sorted(arm, key=str):
    d = arm[k]
    cp = [c[0] for c in d['counter'] if c[0] is not None]
    wavg = sum(c[0]*c[1] for c in d['counter'] if c[0] is not None)/max(1,sum(c[1] for c in d['counter'] if c[0] is not None))
    acc_seats = sum(a[1] for a in d['accept']); acc_rev = sum(a[0]*a[1] for a in d['accept'])
    print(f"  {k}: acc={len(d['accept'])} (seats {acc_seats}, avg ${acc_rev/max(1,acc_seats):.1f}) ctr={len(d['counter'])} [{qs(cp)}] seatw_avg={wavg:.1f} ghost={len(d['ghost'])} pend={len(d['pending'])}")
print("ENT SUBS:", q("SELECT c.group_id g, s.plan, COUNT(*) n, SUM(s.seat_count) seats, ROUND(SUM(s.seat_count*s.effective_price)) mrr, ROUND(SUM(s.seat_count*s.effective_price)/SUM(s.seat_count),1) avgp FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed' GROUP BY 1,2"))
print("ENT status:", q("SELECT c.group_id g, s.status, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' GROUP BY 1,2"))
print("prospects this wk:", q(f"SELECT group_id g, COUNT(*) n FROM customers WHERE customer_type='large' AND created_day>{day-7} GROUP BY 1"))
print("new threads this wk:", q(f"SELECT c.group_id g, COUNT(*) n, SUM(t.seat_count) seats FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE t.turn_number=0 AND t.thread_type='new_lead' AND t.day>{day-7} GROUP BY 1"))
print("usage/seat:", q(f"SELECT c.group_id g, s.plan, COUNT(DISTINCT u.customer_id) n, ROUND(1.0*SUM(u.usage_units)/SUM(s.seat_count),1) per_seat FROM daily_usage u JOIN customers c USING(customer_id) JOIN subscriptions s USING(customer_id) WHERE c.customer_type='large' AND u.day={day} AND s.status='subscribed' GROUP BY 1,2"))
print("ent cancels:", q(f"SELECT c.group_id g, COUNT(*) n, SUM(s.seat_count) seats FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='cancelled' GROUP BY 1"))

