cat > scripts/ent_weekly.py <<'EOF'
# Generic weekly enterprise responder. Config via module-level dicts below.
import novamind_api as nm, json, re, math
from collections import Counter
q=lambda s: nm.query(s)['rows']
day = nm.vars.current_day
CFG = json.loads(open('ent_cfg.json').read()) if False else None
OFFER_PLAN = 'B'          # plan used for all new offers this week
ANCHOR = {'E2': 300, 'E3': 350, 'E1': 200, 'D_E09': 250, 'D_E02': 300, 'D_E07': 600, 'D_E08': 500, 'D_E10': 250, 'D_E01': 500, 'D_E03': 700, 'D_E05': 450, 'D_E04': 600, 'D_E06': 500}
#        reject_below, markup, capbound
PAR = {'E2': (50, 1.06, True), 'E3': (55, 1.06, True), 'E1': (22, 1.05, True), 'D_E09': (28, 1.05, True), 'D_E02': (22, 1.06, True),
       'D_E07': (45, 1.08, True), 'D_E08': (55, 1.08, True), 'D_E10': (28, 1.08, False), 'D_E01': (50, 1.08, False), 'D_E03': (60, 1.08, False), 'D_E05': (40, 1.08, False), 'D_E04': (50, 1.08, False), 'D_E06': (40, 1.08, False)}
groups = [r['g'] for r in q("SELECT DISTINCT group_id g FROM customers WHERE customer_type='large'")]
rows = []
for g in groups:
    rows += q(f'''SELECT t.thread_id tid, t.customer_id cid, c.group_id g, t.seat_count seats, t.day, t.sender, t.turn_number tn, t.thread_type tt, t.offer_json oj, t.message_text mt
FROM enterprise_turns t JOIN customers c USING(customer_id)
WHERE c.group_id='{g}' AND t.message_id IN (SELECT MAX(message_id) FROM enterprise_turns GROUP BY thread_id) AND t.closed=0 AND t.sender!='agent' ''')
print('threads needing response:', len(rows))
tids = [r['tid'] for r in rows if r['sender']=='customer']
nag = {}
for i in range(0, len(tids), 250):
    chunk = ','.join(str(t) for t in tids[i:i+250])
    for x in q(f"SELECT thread_id tid, COUNT(*) n FROM enterprise_turns WHERE sender='agent' AND thread_id IN ({chunk}) GROUP BY 1"): nag[x['tid']] = x['n']
subs = {r['cid']: r for r in q("SELECT s.customer_id cid, s.plan, s.effective_price ep, s.seat_count seats, c.group_id g FROM subscriptions s JOIN customers c USING(customer_id) WHERE c.customer_type='large' AND s.status='subscribed'")}
deals = []; rejects = []; log = Counter(); seats = Counter()
def rd(x): return math.floor(x*2)/2.0
def add(cid, plan, price, tag, g, s):
    deals.append([cid, [[plan, float(price)]]]); log[(g, tag)] += 1; seats[(g, tag)] += s
def rej(cid, tag, g):
    rejects.append({'customer_id': cid}); log[(g, tag)] += 1
for r in rows:
    cid, g, tt, s = r['cid'], r['g'], r['tt'], r['seats']
    if g not in PAR: print('NO PARAMS for group', g); continue
    if r['sender'] == 'system' and tt == 'new_lead':
        add(cid, OFFER_PLAN, ANCHOR[g], 'anchor', g, s); continue
    sb = subs.get(cid)
    if tt == 'churn_prevention':
        if sb: add(cid, sb['plan'], rd(sb['ep']*0.88), 'churn_prev', g, s)
        continue
    o = json.loads(r['oj']) if r['oj'] else {}
    m = re.search(r'Plan ([ABC])', r['mt'] or '')
    if not isinstance(o, dict) or 'price' not in o or not m:
        print('UNPARSED', r['tid'], cid, g, tt, r['oj'], (r['mt'] or '')[:100]); continue
    c = float(o['price']); plan = m.group(1); n = nag.get(r['tid'], 1)
    if tt != 'new_lead':
        if tt != 'renegotiation': print('SPECIAL thread type', tt, cid, g, c, plan, sb)
        if sb and plan != sb['plan'] and c > sb['ep'] + 1:
            add(cid, plan, rd(c*0.97), 'upgrade_accept_counter', g, s)
        else: rej(cid, 'reneg_close', g)
        continue
    rb, mk, capb = PAR[g]
    if c < rb:
        if capb or n >= 3: rej(cid, 'reject_low', g)
        else: add(cid, OFFER_PLAN, ANCHOR[g], 're-anchor', g, s)
    else:
        add(cid, OFFER_PLAN, rd(c*mk), f'acc{mk}', g, s)
print(len(deals), 'deals;', len(rejects), 'rejects')
for k in sorted(log): print('  ', k, log[k], seats.get(k, ''))
for i in range(0, len(rejects), 50):
    res = nm.enterprise.reject_enterprise_deal(deals=rejects[i:i+50])
    bad = [x for x in res['results'] if not x.get('success')]
    if bad: print('reject fails', bad[:3])
ok = 0; fails = []
for i in range(0, len(deals), 50):
    res = nm.enterprise.send_enterprise_deal(deals=deals[i:i+50])
    for x in res.get('results', []):
        if x.get('success'): ok += 1
        else: fails.append(x)
print('deals ok', ok, 'fails', len(fails), fails[:8])
EOF
sed -i '/^CFG = /d' scripts/ent_weekly.py
./novamind-operation python scripts/ent_weekly.py 2>&1 | grep -v request_id

