import novamind_api as nm, json
def p(x): print(json.dumps(x)[:300])
q=lambda s: nm.query(s)['rows']
for t in (1, 3):
    try:
        r = nm.research.start_research_project(tier=t); print('R&D', t, r.get('cost'), r.get('expected_completion_day'))
    except Exception as e: print('R&D err', t, e)
found=[]
for i in range(4):
    r = nm.market.research_market()
    if r.get('discovered_group_id'): found.append(r['discovered_group_id'])
print('discovered:', found)
for g in found:
    r = nm.market.get_group_insights(g)
    print(g, json.dumps({k:v for k,v in r.items() if k in ('group_name','segment','estimates')}))
p(nm.pricing.set_model_tiers(A=2, B=3, C=3))
p(nm.marketing.set_daily_spend(operations=80000, development=100000))
dev = {'E3':15000,'E2':20000,'E1':20000,'D_E09':5000,'D_E02':15000,'D_E07':15000,'D_E08':15000,'D_E01':25000,'D_E03':25000,'D_E10':20000,'D_E05':25000,'D_E04':35000,
       'D_S07':25000,'D_S10':15000,'D_S04':25000,'D_S06':10000,'D_S05':10000,'D_S02':15000,'D_S08':10000,'D_S01':8000,'D_S09':10000,'D_S03':0,'S2':10000,'S3':15000,'S1':0}
for g in found: dev[g] = 30000 if g.startswith('D_E') else 8000
r = nm.analytics.set_targeted_dev_spend(dev); print('dev extra/day', r.get('total_extra_per_day'))
chs = ['social_media','search_ads','linkedin','content_marketing','referral_program']
spend = {c: {} for c in chs}
spend['content_marketing'].update({'S2': 40000, 'D_S10': 10000, 'D_S04': 20000})
spend['referral_program'].update({'S3': 15000, 'D_S07': 40000, 'D_S04': 10000, 'D_S02': 5000, 'D_S05': 5000, 'D_S06': 3000, 'D_S08': 4000})
spend['social_media'].update({'D_S04': 20000, 'D_S02': 5000})
spend['linkedin'].update({'D_S07': 40000, 'D_S10': 10000, 'D_S02': 5000, 'D_S05': 5000, 'D_S06': 3000})
spend['search_ads'].update({'D_S06': 3000, 'D_S08': 4000})
for c in chs:
    for g in ('D_S01','D_S09'): spend[c][g] = 1000
r = nm.marketing.set_targeted_ad_spend(spend); print('ads total/day', r.get('total_per_day'))
p(nm.marketing.post_social_media(content="Competitors shipped big releases this week, so here is ours: every standard plan now runs on a stronger model at the same price, two more research programs landed, and enterprise plans gained the same upgrade. We intend to stay ahead on quality."))
print(q('SELECT SUM(amount) c FROM ledger'))

