                cpr = float(oc['price'])
                if cpr >= 0.5*sb['ep']: add(cid, mp.group(1), rd(cpr), 'churn_prev_accept_counter', g, s)
                else: add(cid, mp.group(1), rd(0.6*sb['ep']), 'churn_prev_floor', g, s)
            else:
                add(cid, sb['plan'], rd(sb['ep']*CHURN_CUT), 'churn_prev', g, s)
        continue"""
assert old in s
s = s.replace(old, new).replace("CHURN_CUT = 0.87", "CHURN_CUT = 0.80")
open('ent_weekly.py','w').write(s)
