import novamind_api as nm
q=lambda s: nm.query(s)['rows']
day = nm.vars.current_day
COST = {'A': 0.002, 'B': 0.006, 'C': 0.012}
rows = q(f"SELECT c.customer_type ct, s.plan, c.group_id g, COUNT(*) n, SUM(u.usage_units) u, SUM(s.seat_count*s.effective_price) mrr FROM daily_usage u JOIN subscriptions s ON s.customer_id=u.customer_id AND s.status='subscribed' JOIN customers c ON c.customer_id=u.customer_id WHERE u.day={day} GROUP BY 1,2,3 ORDER BY 1,2,5 DESC")
tot = {}
for r in rows:
    cost = r['u']*COST[r['plan']]
    tot[r['plan']] = tot.get(r['plan'], 0) + cost
    if cost > 5000: print(r['ct'], r['plan'], r['g'], r['n'], f"usage {r['u']/1e6:.1f}M cost/day {cost/1e3:.0f}K  MRR/day {r['mrr']/30/1e3:.0f}K  margin {(1-cost/(r['mrr']/30))*100:.0f}%")
print({k: round(v/1e3) for k, v in tot.items()})

