import novamind_api as nm, json
from collections import Counter, defaultdict
q=lambda s: nm.query(s)['rows']
day = nm.vars.current_day
res = Counter()
for g in ('D_E03','D_E05','D_E06'):
    t = q(f"SELECT t.thread_id th, t.turn_number tn, t.sender sd, t.day d, t.closed cl, t.close_reason cr FROM enterprise_turns t JOIN customers c USING(customer_id) WHERE c.group_id='{g}' AND t.thread_type='churn_prevention' AND t.thread_id IN (SELECT thread_id FROM enterprise_turns WHERE thread_type='churn_prevention' AND turn_number=0 AND day>{day-40}) ORDER BY t.thread_id, t.message_id")
    th = defaultdict(list)
    for x in t: th[x['th']].append(x)
    for k, turns in th.items():
        # each agent turn: delay since previous turn, and outcome of that agent turn
        for i, x in enumerate(turns):
            if x['sd'] != 'agent': continue
            delay = x['d'] - turns[i-1]['d']
            if x['cl']: oc = 'closed_on_reply:' + str(x['cr'])
            elif i+1 < len(turns): oc = 'next:' + turns[i+1]['sd'] + ':' + str(turns[i+1]['cr'] or 'counter')
            else: oc = 'waiting'
            res[(g, 'turn%d' % x['tn'], 'delay%d' % delay, oc)] += 1
for k in sorted(res): print(k, res[k])

